-- >>> 0024_catalog_today_views.sql
-- ── 0024: expose product_view_counts on public_catalog ───────────────────────
--
-- 0022_conversion_features.sql created `product_view_counts` + the
-- `bump_product_view()` RPC, and apps/web already reads `p.today_views`
-- (ProductCard.tsx:18 → "👁 N people viewed this today"). But 0022 only ever
-- added `stock_qty` to the view, never `today_views` — so the field was always
-- undefined and the label could never render, no matter how many times the RPC
-- fired.
--
-- This appends `today_views` to the view (CREATE OR REPLACE may only append
-- columns, which is why it goes last, right after stock_qty).
--
-- The counter is read-only here: writes still go through bump_product_view(),
-- and pvc_public_read (0022) already lets anon read the table directly.

create or replace view public_catalog as
select p.id, p.org_id, p.kind, p.sku, b.name as brand, p.model, p.collection, p.gender, p.selling_price, p.mrp,
  p.power_eligible, p.featured, p.new_arrival, p.bestseller, p.short_desc, p.description, p.images, p.attrs,
  coalesce((select sum(s.qty) from stock s where s.product_id = p.id), 0) > 0 as in_stock,
  coalesce((select sum(s.qty) from stock s where s.product_id = p.id), 0)::int as stock_qty,
  coalesce(v.today_views, 0)::int as today_views
from products p
  left join brands b on b.id = p.brand_id
  left join product_view_counts v on v.product_id = p.id
where p.visible_on_website and p.status = 'active';

grant select on public_catalog to anon, authenticated;


-- >>> 0025_shape_chip_section.sql
-- ── 0025: register the missing `shape_chip` section ─────────────────────────
--
-- 0023 seeded 18 website_sections rows, but website_content spans 17 section
-- keys and `shape_chip` (the 8 frame-shape buttons) was never given a row.
-- Consequences before this fix:
--   * the ERP Homepage tab fell back to appending it after `footer`
--     (view.tsx sectionKeys), so it sat in the wrong place
--   * it had no row in the Sections tab — could not be hidden or reordered
--   * the public site had no `enabled` flag for it, so it could never be turned
--     off even though every other block could
--
-- It is inserted directly AFTER `frame_finder`, because on the live page the
-- shape grid sits inside the "Find Your Perfect Frame" band. Position is
-- computed from frame_finder's current display_order rather than a literal, so
-- this stays correct even after someone has reordered sections in the ERP.
--
-- `title` is deliberately NULL: that block renders no heading (the heading
-- belongs to frame_finder). Seeding a title would offer the operator a field
-- in the ERP that does nothing on the site.
--
-- Idempotent: the whole body only runs when the row is absent.
--
-- org_id is hardcoded rather than taken from public.current_org(): that
-- function reads the request JWT and is NULL when a migration runs, which
-- aborted the first attempt of this file with a not-null violation. 0023 seeds
-- the same way.

do $$
declare ff_order int;
begin
  if exists (select 1 from website_sections where key = 'shape_chip') then
    return; -- already registered
  end if;

  select display_order into ff_order from website_sections where key = 'frame_finder';
  ff_order := coalesce(ff_order, 6);

  insert into website_sections (org_id, key, title, subtitle, enabled, display_order)
  values ('00000000-0000-0000-0000-000000000001', 'shape_chip', null, null, true, ff_order + 1);

  -- Make room: everything currently after frame_finder moves down one.
  -- (lenses_guide at 99 shifts to 100 — correct, it is also after frame_finder.)
  update website_sections
     set display_order = display_order + 1
   where display_order > ff_order
     and key <> 'shape_chip';
end $$;


-- >>> 0026_settings_system.sql
-- 0026_settings_system.sql
-- Settings system: DB-driven WhatsApp message templates, settings-driven code
-- prefixes, and a public read view for the website (contact/analytics).

-- ── 1. Message templates ─────────────────────────────────────────────────────
-- body_staff = warm, full version staff send personally via wa.me
-- body_auto  = short version for automations / quick sends
-- meta_template = approved Meta WhatsApp template name (API automations)
create table if not exists message_templates (
  id            uuid primary key default gen_random_uuid(),
  org_id        uuid not null default public.current_org() references organizations(id),
  key           text not null,
  category      text not null default 'general',
  name          text not null,
  body_auto     text not null,
  body_staff    text not null,
  meta_template text,
  variables     text[] not null default '{}',
  sort_order    int not null default 0,
  is_active     boolean not null default true,
  created_at    timestamptz default now(),
  updated_at    timestamptz default now(),
  unique (org_id, key)
);

alter table message_templates enable row level security;

drop policy if exists mt_select on message_templates;

drop policy if exists mt_insert on message_templates;

drop policy if exists mt_update on message_templates;

drop policy if exists mt_delete on message_templates;

create policy mt_select on message_templates for select using (org_id = public.current_org());

create policy mt_insert on message_templates for insert with check (org_id = public.current_org() and public.is_admin());

create policy mt_update on message_templates for update using (org_id = public.current_org() and public.is_admin());

create policy mt_delete on message_templates for delete using (org_id = public.current_org() and public.is_admin());

